CREATE TABLE fundos (id INTEGER PRIMARY KEY, codigo TEXT NOT NULL, estrutura TEXT, nome TEXT, nome_key TEXT, cnpj_classe TEXT, cnpj_fundo TEXT, status TEXT, inicio TEXT, ano INTEGER, subclasses INTEGER, data_ref TEXT, pl REAL, cotistas INTEGER, cota REAL, foco TEXT, nivel1 TEXT, nivel2 TEXT, nivel3 TEXT)
CREATE INDEX ix_fundos_nivel1 ON fundos(nivel1)
CREATE INDEX ix_fundos_nivel2 ON fundos(nivel2)
CREATE INDEX ix_fundos_nivel3 ON fundos(nivel3)
CREATE INDEX ix_fundos_ano ON fundos(ano)
CREATE INDEX ix_fundos_inicio ON fundos(inicio)
CREATE INDEX ix_fundos_pl ON fundos(pl)
CREATE INDEX ix_fundos_cotistas ON fundos(cotistas)
